import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import path from "node:path";
import test from "node:test";

/**
 * Dependency-free guard for the CI workflow. The file is small and generated by
 * hand, so a line-oriented reader is enough to assert the invariants that matter
 * (least privilege, SHA-pinned actions, `npm ci`, and the full check sequence).
 */
const workflowPath = path.join(
	import.meta.dirname,
	"..",
	".github",
	"workflows",
	"ci.yml",
);
const workflow = readFileSync(workflowPath, "utf8");
const lines = workflow.split("\n");

function section(header) {
	const start = lines.findIndex((line) => line.trim() === header);
	assert.notEqual(start, -1, `${header} must exist in the workflow`);
	let end = lines.length;
	for (let index = start + 1; index < lines.length; index += 1) {
		if (/^\S/.test(lines[index])) {
			end = index;
			break;
		}
	}
	return lines.slice(start, end).join("\n");
}

function job(name) {
	return section(`${name}:`);
}

test("the workflow runs with least privilege and cancels superseded runs", () => {
	const permissions = section("permissions:");
	assert.match(permissions, /contents:\s*read/);
	assert.doesNotMatch(permissions, /write/);

	const concurrency = section("concurrency:");
	assert.match(concurrency, /group:\s*\$\{\{\s*github\.workflow\s*\}\}/);
	assert.match(concurrency, /cancel-in-progress:\s*true/);
});

test("triggers stay read-only and never use privileged events", () => {
	const triggers = section("on:");
	assert.match(triggers, /pull_request:/);
	assert.match(triggers, /workflow_dispatch:/);
	assert.doesNotMatch(triggers, /pull_request_target/);
	// One line at a time, so a later "| sha256sum" is not read as "| sh".
	assert.doesNotMatch(workflow, /curl\s+[^|\n]*\|\s*(sudo\s+)?(ba)?sh\b/);
});

test("every job sets a timeout, checks out without credentials, and pins Node", () => {
	const jobs = section("jobs:");
	const jobNames = [...jobs.matchAll(/^ {2}([a-z][a-z0-9-]*):$/gm)].map(
		(match) => match[1],
	);
	assert.deepEqual(jobNames.sort(), [
		"actionlint",
		"backend",
		"frontend",
		"preflight",
		"secrets",
	]);

	for (const name of jobNames) {
		const body = job(name);
		assert.match(
			body,
			/timeout-minutes:\s*\d+/,
			`${name} must bound its runtime`,
		);
		assert.match(
			body,
			/uses:\s*actions\/checkout@[0-9a-f]{40} # v\d+/,
			`${name} must pin checkout`,
		);
		assert.match(
			body,
			/persist-credentials:\s*false/,
			`${name} must not persist credentials`,
		);
		// actionlint and gitleaks are single verified binaries and need no Node runtime.
		if (name === "actionlint" || name === "secrets") continue;
		assert.match(
			body,
			/uses:\s*actions\/setup-node@[0-9a-f]{40} # v\d+/,
			`${name} must pin setup-node`,
		);
		assert.match(
			body,
			/node-version-file:\s*\.nvmrc/,
			`${name} must use the pinned Node version`,
		);
	}
});

test("both application jobs install from the lockfile and run the full check sequence", () => {
	for (const name of ["frontend", "backend"]) {
		const body = job(name);
		assert.match(
			body,
			/run:\s*npm ci\b/,
			`${name} must install from its lockfile`,
		);
		assert.doesNotMatch(
			body,
			/run:\s*npm install\b/,
			`${name} must not resolve new versions`,
		);
		assert.match(body, /npm audit/, `${name} must audit dependencies`);

		const commands = [...body.matchAll(/run:\s*(npm[^"\n]*)/g)].map((match) =>
			match[1].trim(),
		);
		// Drop trailing flags so "npm audit --audit-level=high" compares as "npm audit".
		const order = commands.map((command) =>
			command.replace(/\s+--.*$/, "").trim(),
		);
		for (const expected of [
			"npm audit",
			"npm run lint",
			"npm test",
			"npm run typecheck",
			"npm run build",
		]) {
			assert.ok(order.includes(expected), `${name} must run "${expected}"`);
			assert.ok(
				order.indexOf(expected) > order.indexOf("npm ci"),
				`${name} must run "${expected}" after installation`,
			);
		}
		assert.ok(
			order.indexOf("npm run typecheck") < order.indexOf("npm run build"),
			`${name} must typecheck before building`,
		);
	}
});

test("no job-level condition calls hashFiles, which GitHub rejects outside steps", () => {
	for (const name of ["frontend", "backend", "preflight"]) {
		const jobLevel = job(name)
			.split("\n")
			.filter((line) => /^ {4}\S/.test(line));
		assert.ok(
			!jobLevel.some((line) => /^ {4}if:.*hashFiles\(/.test(line)),
			`${name} must not use hashFiles() in its job-level if`,
		);
	}
});

test("the preflight job enforces demo readiness in strict mode", () => {
	const body = job("preflight");
	assert.match(body, /node tools\/demo-readiness\.mjs --strict/);
});

test("the actionlint job verifies the downloaded binary before running it", () => {
	const body = job("actionlint");
	assert.match(body, /ACTIONLINT_VERSION:\s*\d+\.\d+\.\d+/);
	assert.match(body, /ACTIONLINT_SHA256:\s*[0-9a-f]{64}/);
	assert.match(body, /sha256sum --check --strict/);
	assert.ok(
		body.indexOf("sha256sum") < body.indexOf("./actionlint"),
		"the checksum must be verified before actionlint runs",
	);
});

test("the secret scan verifies gitleaks and scans the full history", () => {
	const body = job("secrets");
	assert.match(body, /GITLEAKS_SHA256:\s*[0-9a-f]{64}/);
	assert.match(body, /sha256sum --check --strict/);
	assert.match(body, /fetch-depth:\s*0/);
	assert.match(body, /gitleaks git [^\n]*--redact[^\n]*--exit-code 1/);
});
